<script setup>
import PartnerLayout from '@/Layouts/PartnerLayout.vue'; import Pagination from '@/Components/Partner/Pagination.vue'; import FormErrors from '@/Components/Partner/FormErrors.vue'; import { useForm } from '@inertiajs/vue3'; import { ref } from 'vue';
defineProps({customers:Object}); const editing=ref(null); const form=useForm({name:'',email:'',phone:'',type:'organization'});
const edit=client=>{editing.value=client.uuid;form.name=client.name;form.email=client.email;form.phone=client.phone||'';form.type=client.type;form.clearErrors();};
const reset=()=>{editing.value=null;form.reset();};
const submit=()=>{const options={preserveScroll:true,onSuccess:reset};editing.value?form.put(route('partner.customers.update',editing.value),options):form.post(route('partner.customers.store'),options);};
</script>
<template><PartnerLayout title="Clients / customers"><form class="form-card mb-6" @submit.prevent="submit"><h2 class="text-xl font-bold">{{ editing?'Edit client':'Add a client' }}</h2><FormErrors :errors="form.errors"/><div class="form-grid"><label>Client name<input v-model="form.name" required maxlength="255"/></label><label>Contact email<input v-model="form.email" type="email" required/></label><label>Phone<input v-model="form.phone" type="tel" maxlength="30"/></label><label v-if="!editing">Account type<select v-model="form.type"><option value="organization">Organisation</option><option value="individual">Individual</option></select></label></div><div class="flex gap-4"><button class="form-button" :disabled="form.processing">{{ editing?'Save changes':'Add client' }}</button><button v-if="editing" type="button" @click="reset">Cancel</button></div></form><div class="space-y-3"><article v-for="client in customers.data" :key="client.uuid" class="flex flex-wrap items-center justify-between gap-4 rounded-xl bg-white p-5"><div><h2 class="font-bold">{{ client.name }}</h2><p class="text-sm text-slate-600">{{ client.customer_number }} ? {{ client.email }} ? {{ client.phone }}</p></div><button class="font-bold text-cyan-700" @click="edit(client)">Edit</button></article><p v-if="!customers.data.length">No clients yet. Add your first client above.</p></div><Pagination :page="customers"/></PartnerLayout></template>
